WITH RECURSIVE `numbers` AS (SELECT CAST(1 AS BIGINT) AS `n`, CAST(1 AS BIGINT) AS `square`, CAST(1 AS BIGINT) AS `cc` UNION ALL SELECT `numbers`.`n` + 1 AS `n + 1`, (`numbers`.`n` + 1) * (`numbers`.`n` + 1) AS `(n + 1) * (n + 1)`, ((`numbers`.`n` + 1) * (`numbers`.`n` + 1)) * (`numbers`.`n` + 1) AS `((n + 1) * (n + 1)) * (n + 1)` FROM `numbers` WHERE `numbers`.`n` < 10) SELECT `numbers`.`n`, `numbers`.`square`, `numbers`.`cc` FROM `numbers` ORDER BY `numbers`.`n` ASC;
